import json, hashlib
from collections import Counter
from pathlib import Path
from forge.compiler import compile_query
from forge.assurance import assure_compiled_sql, QueryAssuranceError
p=Path("docs/archive/benchmarks/benchmark-sol-error-triage-2026-09-05.json")
b=p.read_bytes(); data=json.loads(b)
order=["cte","scan","joins","filter","group","agg","window","having","qualify","select","distinct","sort","limit","offset","explain","union","intersect","except"]
def reorder(x):
    if isinstance(x,list): return [reorder(v) for v in x]
    if not isinstance(x,dict): return x
    keys=[k for k in order if k in x]+[k for k in x if k not in order] if "scan" in x and "select" in x else x.keys()
    return {k:reorder(x[k]) for k in keys}
def outcome(q):
    try: return {"sql":compile_query(q,dialect="sqlite")}
    except ValueError as e: return {"error":str(e)}
changes=[]; statuses=Counter(); ordered=0
for c in data["cases"]:
    q=c["arms"]["forge"]["candidate"]; r=reorder(q)
    assert q==r
    ordered+=json.dumps(q)!=json.dumps(r)
    a,z=outcome(q),outcome(r)
    statuses["compiled" if "sql" in a else "rejected"]+=1
    if a!=z: changes.append(c["case_id"])
assert not changes
bad={"scan":"facts","agg":[{"fn":"sum","col":"facts.amount","as":"total"}],"select":["missing"]}
local=outcome(bad)
try:
    assure_compiled_sql(local["sql"],dialect="sqlite",input_kind="forge_json",allowed_tables=["facts"],registry_snapshot={"tables":{"facts":{"columns":{"amount":{}}}}})
    gate="allowed"
except QueryAssuranceError as e:
    gate=type(e).__name__
print(json.dumps({"source":str(p),"source_sha256":hashlib.sha256(b).hexdigest(),"cases":len(data["cases"]),"compile_status":dict(statuses),"serialization_changed":ordered,"compile_or_error_changed":changes,"candidate_values_changed":0,"gold_executions":0,"new_model_calls":0,"new_sql_executions":0,"invalid_shape_valid_query":{"sql":local.get("sql"),"assurance":gate},"candidate_order":order},indent=2))
